questionCpp:
#include <iostream>
using namespace std;

int mystery(int a, int b) {
    if (a > b)
        return a * 2 - b;
    else
        return b * 2 - a;
}

int main() {
    int x = mystery(5, 3);
    int y = mystery(4, 7);
    int z = x + y;
    cout << z << endl;
    return 0;
}

#include <iostream>
using namespace std;

int transform(int n) {
    int total = 0;
    for (int i = 1; i <= n; i++)
        total += i * 2;
    return total;
}

int main() {
    int result = transform(4) + transform(3);
    cout << result << endl;
    return 0;
}

